'use strict';

const { walkTree } = require('../utils/helpers');

/**
 * Extract all prototype interactions from a Figma document.
 * Interactions live on nodes as `reactions` arrays.
 *
 * @param {object} document - Figma document root
 * @returns {object[]} Array of normalised interaction descriptors
 */
function extractInteractions(document) {
  if (!document) return [];

  const interactions = [];

  walkTree(document, (node) => {
    if (!Array.isArray(node.reactions) || node.reactions.length === 0) return;
    for (const reaction of node.reactions) {
      interactions.push(_normaliseReaction(node, reaction));
    }
  });

  return interactions;
}

function _normaliseReaction(node, reaction) {
  return {
    sourceNodeId: node.id,
    sourceNodeName: node.name,
    sourceNodeType: node.type,
    trigger: _normaliseTrigger(reaction.trigger),
    action: _normaliseAction(reaction.action),
  };
}

function _normaliseTrigger(trigger) {
  if (!trigger) return { type: 'UNKNOWN' };

  const base = { type: trigger.type };

  switch (trigger.type) {
    case 'ON_CLICK':
    case 'ON_PRESS':
    case 'ON_RELEASE':
    case 'ON_HOVER':
    case 'ON_DRAG':
    case 'MOUSE_ENTER':
    case 'MOUSE_LEAVE':
    case 'MOUSE_UP':
    case 'MOUSE_DOWN':
      return base;

    case 'AFTER_TIMEOUT':
      return { ...base, timeoutMs: (trigger.timeout || 0) * 1000 };

    case 'ON_KEY_DOWN':
      return { ...base, keyCodes: trigger.keyCodes || [] };

    case 'ON_MEDIA_HIT':
    case 'ON_MEDIA_END':
      return base;

    default:
      return { type: trigger.type || 'UNKNOWN', raw: trigger };
  }
}

function _normaliseAction(action) {
  if (!action) return { type: 'NONE' };

  const base = { type: action.type };

  switch (action.type) {
    case 'NAVIGATE':
      return {
        ...base,
        destinationId: action.destinationId || null,
        transition: _normaliseTransition(action.transition),
        preserveScrollPosition: action.preserveScrollPosition ?? false,
        resetVideoPosition: action.resetVideoPosition ?? false,
      };

    case 'OVERLAY':
      return {
        ...base,
        destinationId: action.destinationId || null,
        overlayRelativePosition: action.overlayRelativePosition || null,
        transition: _normaliseTransition(action.transition),
      };

    case 'SWAP':
      return {
        ...base,
        destinationId: action.destinationId || null,
        transition: _normaliseTransition(action.transition),
      };

    case 'SCROLL_TO':
      return {
        ...base,
        destinationId: action.destinationId || null,
        disableScrollAnimation: action.disableScrollAnimation ?? false,
      };

    case 'BACK':
    case 'CLOSE':
      return base;

    case 'URL':
      return { ...base, url: action.url || '' };

    case 'NODE':
      return {
        ...base,
        destinationId: action.destinationId || null,
        transition: _normaliseTransition(action.transition),
        navigation: action.navigation || 'NAVIGATE',
        preserveScrollPosition: action.preserveScrollPosition ?? false,
        overlayRelativePosition: action.overlayRelativePosition || null,
        resetScrollPosition: action.resetScrollPosition ?? false,
        resetInteractiveComponents: action.resetInteractiveComponents ?? false,
        resetVideoPosition: action.resetVideoPosition ?? false,
        resetScrollInteractions: action.resetScrollInteractions ?? false,
      };

    default:
      return { ...base, raw: action };
  }
}

function _normaliseTransition(transition) {
  if (!transition) return null;
  return {
    type: transition.type,           // DISSOLVE | SMART_ANIMATE | MOVE_IN | MOVE_OUT | PUSH | SLIDE_IN | SLIDE_OUT | NONE
    duration: transition.duration ?? 0.3,
    easing: transition.easing?.type || 'LINEAR',
    direction: transition.direction || null,
  };
}

module.exports = { extractInteractions };

