'use strict';

/**
 * Extract prototype flows and starting points from a Figma file.
 *
 * A "flow" in Figma is defined by a prototypeDevice + flowStartingPoints
 * on each page, plus the interaction graph built from node reactions.
 *
 * @param {object} figmaFile - Full Figma file response (from GET /v1/files/:key)
 * @returns {object[]} Array of normalised flow descriptors
 */
function extractFlows(figmaFile) {
  if (!figmaFile || !figmaFile.document) return [];

  const flows = [];
  const document = figmaFile.document;

  for (const page of (document.children || [])) {
    if (page.type !== 'CANVAS') continue;

    const prototypeDevice = page.prototypeDevice || null;
    const startingPoints = Array.isArray(page.flowStartingPoints)
      ? page.flowStartingPoints
      : [];

    if (startingPoints.length === 0) continue;

    for (const sp of startingPoints) {
      const startNode = _findNodeById(page, sp.nodeId);
      flows.push({
        flowId: sp.nodeId,
        flowName: sp.name || startNode?.name || 'Unnamed Flow',
        pageId: page.id,
        pageName: page.name,
        startNodeId: sp.nodeId,
        startNodeName: startNode?.name || null,
        prototypeDevice: prototypeDevice ? _normaliseDevice(prototypeDevice) : null,
        // Build the complete interaction graph reachable from this starting point
        graph: _buildFlowGraph(page, sp.nodeId),
      });
    }
  }

  return flows;
}

/**
 * BFS through the interaction graph starting from startNodeId.
 * Returns all reachable nodes and the edges between them.
 */
function _buildFlowGraph(page, startNodeId) {
  const visited = new Set();
  const nodes = [];
  const edges = [];
  const queue = [startNodeId];

  // Build a flat nodeId → node map for the page
  const nodeMap = {};
  _buildNodeMap(page, nodeMap);

  while (queue.length) {
    const nodeId = queue.shift();
    if (visited.has(nodeId)) continue;
    visited.add(nodeId);

    const node = nodeMap[nodeId];
    if (!node) continue;

    nodes.push({ id: nodeId, name: node.name, type: node.type });

    for (const reaction of (node.reactions || [])) {
      const action = reaction.action || {};
      const destId = action.destinationId || action.destinationID;
      if (!destId) continue;

      edges.push({
        from: nodeId,
        to: destId,
        trigger: reaction.trigger?.type || 'UNKNOWN',
        action: action.type || 'UNKNOWN',
        transition: action.transition
          ? {
              type: action.transition.type,
              duration: action.transition.duration,
              easing: action.transition.easing?.type || 'LINEAR',
            }
          : null,
      });

      if (!visited.has(destId)) queue.push(destId);
    }
  }

  return { nodes, edges };
}

function _buildNodeMap(node, map) {
  if (!node) return;
  map[node.id] = node;
  for (const child of (node.children || [])) {
    _buildNodeMap(child, map);
  }
}

function _findNodeById(page, id) {
  const map = {};
  _buildNodeMap(page, map);
  return map[id] || null;
}

function _normaliseDevice(device) {
  return {
    type: device.type || 'NONE',
    rotation: device.rotation || 'NONE',
    presetIdentifier: device.deviceId || null,
    size: device.size ? { width: device.size.width, height: device.size.height } : null,
  };
}

module.exports = { extractFlows };

