const { render } = require('../../renderers/markdownRenderer');
const { validateFileKey, validateFigmaQueryParams } = require('../../middleware/validate');
const logger = require('../../utils/logger');

const router = Router();

// One shared client instance per process
const figma = new FigmaClient();

// ---------------------------------------------------------------------------
// Helper: parse common normalizer options from query string
// ---------------------------------------------------------------------------
function parseNormalizerOpts(query) {
  return {
    includeLayout:       query.includeLayout       !== false,
    includeInteractions: query.includeInteractions  !== false,
    includeText:         query.includeText          !== false,
    includeComponents:   query.includeComponents    !== false,
    includeFlows:        query.includeFlows         !== false,
  };
}

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/json
// Returns the full normalised JSON for a Figma file.
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/json',
  validateFileKey,
  validateFigmaQueryParams,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      const { version } = req.query;

      logger.info(`[JSON] Fetching file: ${fileKey}`);

      const [fileData, stylesData] = await Promise.all([
        figma.getFile(fileKey, version ? { version } : {}),
        figma.getStyles(fileKey).catch(() => ({})),
      ]);

      const normalised = normalize(fileData, stylesData, parseNormalizerOpts(req.query));

      res.json({
        ok: true,
        fileKey,
        data: normalised,
      });
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/markdown
// Returns Figma file rendered as Markdown.
// Query params:
//   perPage=true  → returns { pages: { [pageName]: string } }
//   download=true → sets Content-Disposition: attachment
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/markdown',
  validateFileKey,
  validateFigmaQueryParams,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      const { version, perPage, download } = req.query;

      logger.info(`[Markdown] Fetching file: ${fileKey}`);

      const [fileData, stylesData] = await Promise.all([
        figma.getFile(fileKey, version ? { version } : {}),
        figma.getStyles(fileKey).catch(() => ({})),
      ]);

      const normalised = normalize(fileData, stylesData, parseNormalizerOpts(req.query));
      const rendered   = render(normalised, { perPage: Boolean(perPage) });

      if (perPage) {
        // Return a JSON map of { pageName: markdownString }
        return res.json({ ok: true, fileKey, pages: rendered });
      }

      // Return raw Markdown
      if (download) {
        const filename = `${fileKey}-figma.md`;
        res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
      }

      res.type('text/markdown; charset=utf-8').send(rendered);
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/nodes
// Returns normalised JSON for specific node IDs only.
// Query: nodeIds=id1,id2,id3 (required)
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/nodes',
  validateFileKey,
  validateFigmaQueryParams,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      const nodeIds = req.parsedNodeIds;

      if (!nodeIds || nodeIds.length === 0) {
        return res.status(400).json({
          error: { type: 'VALIDATION_ERROR', message: 'Query param nodeIds is required.' },
        });
      }

      logger.info(`[Nodes] Fetching ${nodeIds.length} nodes from ${fileKey}`);
      const data = await figma.getFileNodes(fileKey, nodeIds);

      res.json({ ok: true, fileKey, nodeIds, data });
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/images
// Returns render URLs for specific node IDs.
// Query: nodeIds=id1,id2  format=png|jpg|svg|pdf  scale=1-4
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/images',
  validateFileKey,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      const { nodeIds, format = 'png', scale = '1' } = req.query;

      if (!nodeIds) {
        return res.status(400).json({
          error: { type: 'VALIDATION_ERROR', message: 'Query param nodeIds is required.' },
        });
      }

      const ids = nodeIds.split(',').map((s) => s.trim()).filter(Boolean);
      const scaleNum = Math.min(Math.max(parseFloat(scale) || 1, 0.01), 4);

      logger.info(`[Images] Rendering ${ids.length} nodes as ${format} @${scaleNum}x`);
      const data = await figma.getImages(fileKey, ids, { format, scale: scaleNum });

      res.json({ ok: true, fileKey, format, scale: scaleNum, images: data.images || {} });
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/components
// Returns component metadata for the file.
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/components',
  validateFileKey,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      logger.info(`[Components] Fetching components for ${fileKey}`);
      const data = await figma.getComponents(fileKey);
      res.json({ ok: true, fileKey, data });
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/styles
// Returns design style metadata.
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/styles',
  validateFileKey,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      logger.info(`[Styles] Fetching styles for ${fileKey}`);
      const data = await figma.getStyles(fileKey);
      res.json({ ok: true, fileKey, data });
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/versions
// Returns version history.
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/versions',
  validateFileKey,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      logger.info(`[Versions] Fetching versions for ${fileKey}`);
      const data = await figma.getVersions(fileKey);
      res.json({ ok: true, fileKey, data });
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/flows
// Returns extracted prototype flows only (no full file normalisation).
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/flows',
  validateFileKey,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      logger.info(`[Flows] Extracting flows for ${fileKey}`);

      const fileData = await figma.getFile(fileKey);
      const { extractFlows } = require('../../extractors/flowExtractor');
      const flows = extractFlows(fileData);

      res.json({ ok: true, fileKey, flowCount: flows.length, flows });
    } catch (err) {
      next(err);
    }
  }
);

// ---------------------------------------------------------------------------
// GET /api/figma/:fileKey/interactions
// Returns extracted interactions only.
// ---------------------------------------------------------------------------
router.get(
  '/:fileKey/interactions',
  validateFileKey,
  async (req, res, next) => {
    try {
      const { fileKey } = req.params;
      logger.info(`[Interactions] Extracting interactions for ${fileKey}`);

      const fileData = await figma.getFile(fileKey);
      const { extractInteractions } = require('../../extractors/interactionExtractor');
      const interactions = extractInteractions(fileData.document);

      res.json({ ok: true, fileKey, interactionCount: interactions.length, interactions });
    } catch (err) {
      next(err);
    }
  }
);

module.exports = router;

